function new_tenant_code(PDO $pdo): string { do {$code='FORA-'.strtoupper(bin2hex(random_bytes(4)));$q=$pdo->prepare('SELECT 1 FROM tenants WHERE code=?');$q->execute([$code]);} while($q->fetchColumn());return $code; }
function receipt_code(string $prefix): string {return $prefix.'-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));}
function upload_file($key){
    if(empty($_FILES[$key]['name']))return null;
    if($_FILES[$key]['error']!==UPLOAD_ERR_OK||$_FILES[$key]['size']>8*1024*1024)throw new RuntimeException('Upload failed or file exceeds 8 MB.');
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES[$key]['tmp_name']);
    $ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'][$mime]??null;
    if(!$ext)throw new RuntimeException('Use a JPG, PNG, WebP, or PDF file.');
    if(!is_dir(__DIR__.'/uploads'))mkdir(__DIR__.'/uploads',0755,true);
    $name=bin2hex(random_bytes(16)).'.'.$ext;
    if(!move_uploaded_file($_FILES[$key]['tmp_name'],__DIR__.'/uploads/'.$name))throw new RuntimeException('Could not save uploaded file.');
    return 'uploads/'.$name;
}
