        if($action==='mobile-wallet'){$sales=$pdo->prepare('SELECT sale_date AS entry_date,sale_amount AS amount,payment_mode,payment_method FROM mobile_sales WHERE company_id=?');$sales->execute([$companyId]);$purchases=$pdo->prepare('SELECT p.purchase_date AS entry_date,p.total_amount AS amount,p.invoice_number,s.supplier_name FROM mobile_purchases p LEFT JOIN mobile_suppliers s ON s.id=p.supplier_id AND s.company_id=p.company_id WHERE p.company_id=?');$purchases->execute([$companyId]);$expenses=$pdo->prepare('SELECT expense_date AS entry_date,name,description,amount FROM mobile_expenses WHERE company_id=?');$expenses->execute([$companyId]);$withdrawals=$pdo->prepare('SELECT id,withdrawal_date AS entry_date,amount,name,notes,movement_type,wallet_account FROM mobile_wallet_withdrawals WHERE company_id=?');$withdrawals->execute([$companyId]);$supplierPayments=$pdo->prepare('SELECT payment_date AS entry_date,amount,payment_method FROM mobile_supplier_payments WHERE company_id=?');$supplierPayments->execute([$companyId]);$customerPayments=$pdo->prepare('SELECT payment_date AS entry_date,amount,payment_method FROM mobile_customer_payments WHERE company_id=?');$customerPayments->execute([$companyId]);$cheques=$pdo->prepare("SELECT COALESCE(status_date,cheque_date) AS entry_date,amount,cheque_direction FROM mobile_cheques WHERE company_id=? AND status='Cleared'");$cheques->execute([$companyId]);$transfers=$pdo->prepare('SELECT transfer_date AS entry_date,amount FROM mobile_wallet_transfers WHERE company_id=?');$transfers->execute([$companyId]);$opening=$pdo->prepare('SELECT effective_date,cash_amount,bank_amount,notes FROM mobile_wallet_opening_balances WHERE company_id=?');$opening->execute([$companyId]);$openingBalance=$opening->fetch()?:['effective_date'=>null,'cash_amount'=>'0.00','bank_amount'=>'0.00','notes'=>null];out(['today'=>$pdo->query('SELECT CURDATE()')->fetchColumn(),'sales'=>$sales->fetchAll(),'purchases'=>$purchases->fetchAll(),'expenses'=>$expenses->fetchAll(),'withdrawals'=>$withdrawals->fetchAll(),'supplier_payments'=>$supplierPayments->fetchAll(),'customer_payments'=>$customerPayments->fetchAll(),'cheques'=>$cheques->fetchAll(),'transfers'=>$transfers->fetchAll(),'opening_balance'=>$openingBalance]);}
        if($action==='mobile-customer-wallet'){$q=$pdo->prepare('SELECT id,name,trn,emirate,mobile FROM mobile_clients WHERE company_id=? ORDER BY name');$q->execute([$companyId]);$clients=$q->fetchAll();$q=$pdo->prepare('SELECT s.id,s.customer_id,s.bill_number,s.sale_date,s.item_name,s.model,s.sale_amount,s.payment_mode,COALESCE(SUM(p.amount),0) payments_total FROM mobile_sales s LEFT JOIN mobile_customer_payments p ON p.sale_id=s.id AND p.company_id=s.company_id WHERE s.company_id=? AND s.customer_id IS NOT NULL GROUP BY s.id ORDER BY s.sale_date DESC,s.id DESC');$q->execute([$companyId]);$bills=$q->fetchAll();$clientMap=[];foreach($clients as $i=>$c){$clients[$i]['balance']=0.0;$clients[$i]['credit_sales']=0;$clientMap[(int)$c['id']]=$i;}foreach($bills as &$bill){$bill['paid_amount']=$bill['payment_mode']==='Credit'?(float)$bill['payments_total']:(float)$bill['sale_amount'];$bill['balance_amount']=$bill['payment_mode']==='Credit'?max(0,round((float)$bill['sale_amount']-(float)$bill['paid_amount'],2)):0.0;$bill['status']=$bill['balance_amount']>0?'Credit':'Paid';unset($bill['payments_total']);if(isset($clientMap[(int)$bill['customer_id']])&&$bill['payment_mode']==='Credit'){$i=$clientMap[(int)$bill['customer_id']];$clients[$i]['balance']+=$bill['balance_amount'];$clients[$i]['credit_sales']++;}}unset($bill);out(['clients'=>$clients,'bills'=>$bills]);}
