        if($action==='units'){$id=(int)($_GET['property_id']??0);$from=$_GET['from_date']??'';$to=$_GET['to_date']??'';$validDate=fn($v)=>is_string($v)&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$v);$from=$validDate($from)?$from:date('Y-m-d');$to=$validDate($to)?$to:$from;$s=$pdo->prepare('SELECT u.*,p.name property_name,p.code property_code,p.type property_type,p.emirate,p.area, EXISTS(SELECT 1 FROM tenancies t WHERE t.unit_id=u.id AND t.status="Active" AND CURDATE() BETWEEN t.start_date AND t.end_date) occupied, NOT EXISTS(SELECT 1 FROM tenancies a WHERE a.unit_id=u.id AND a.status="Active" AND a.start_date<=? AND a.end_date>=?) available_for_dates FROM units u JOIN properties p ON p.id=u.property_id WHERE (?=0 OR p.id=?) AND u.company_id=? ORDER BY p.name,u.room_number');$s->execute([$to,$from,$id,$id,$companyId]);out($s->fetchAll());}
        if($action==='realestate-vat-report'){$rent=$pdo->prepare('SELECT tn.id,tn.contract_date transaction_date,"Rent" supply_type,tn.status,tn.yearly_rent net_amount,tn.vat_rate,tn.vat_treatment,tn.vat_amount,tn.total_amount,CONCAT("RENT-",LPAD(tn.id,6,"0")) reference,t.name tenant_name,t.vat_id,p.name property_name,p.type property_type,u.room_number FROM tenancies tn JOIN tenants t ON t.id=tn.tenant_id AND t.company_id=tn.company_id JOIN units u ON u.id=tn.unit_id AND u.company_id=tn.company_id JOIN properties p ON p.id=u.property_id AND p.company_id=u.company_id WHERE tn.company_id=? ORDER BY tn.contract_date DESC,tn.id DESC');$rent->execute([$companyId]);$bills=$pdo->prepare('SELECT b.id,b.bill_date transaction_date,"Bill" supply_type,b.status,b.amount net_amount,5.00 vat_rate,"Standard Rated" vat_treatment,b.vat_amount,b.total_amount,COALESCE(b.receipt_no,CONCAT("BILL-",LPAD(b.id,6,"0"))) reference,COALESCE(t.name,"") tenant_name,t.vat_id,p.name property_name,p.type property_type,u.room_number,b.description FROM bills b LEFT JOIN tenants t ON t.id=b.tenant_id AND t.company_id=b.company_id LEFT JOIN tenancies tn ON tn.id=b.tenancy_id AND tn.company_id=b.company_id LEFT JOIN units u ON u.id=tn.unit_id LEFT JOIN properties p ON p.id=u.property_id WHERE b.company_id=? AND b.status<>"Draft" ORDER BY b.bill_date DESC,b.id DESC');$bills->execute([$companyId]);out(['tenancies'=>$rent->fetchAll(),'bills'=>$bills->fetchAll()]);}
if($action==='tenants'){$q=$pdo->prepare('SELECT t.*,tn.id tenancy_id,tn.previous_tenancy_id,tn.unit_id,tn.contract_date,tn.start_date,tn.end_date,tn.yearly_rent,tn.vat_amount,tn.vat_rate,tn.vat_treatment,tn.total_amount,tn.first_payment_cash,tn.agreement_path,tn.status,tn.purpose,tn.free_months,tn.payment_mode,tn.commission_amount,tn.security_amount,tn.sewa_account,tn.notes,p.name property_name,p.code property_code,p.emirate,p.area,u.room_number FROM tenants t LEFT JOIN tenancies tn ON tn.tenant_id=t.id LEFT JOIN units u ON u.id=tn.unit_id LEFT JOIN properties p ON p.id=u.property_id WHERE t.company_id=? ORDER BY tn.end_date DESC');$q->execute([$companyId]);out($q->fetchAll());}
